CREATE   PROCEDURE [synapse_ce].[usp_Update_apuk_localgroup]
AS
BEGIN
	UPDATE tgt SET 
		tgt.[apuk_code] = stg.[apuk_code],
		tgt.[apuk_countryid] = stg.[apuk_countryid],
		tgt.[apuk_countryid_entitytype] = stg.[apuk_countryid_entitytype],
		tgt.[apuk_countryidname] = stg.[apuk_countryidname],
		tgt.[apuk_localgroupid] = stg.[apuk_localgroupid],
		tgt.[apuk_localofficeid] = stg.[apuk_localofficeid],
		tgt.[apuk_localofficeid_entitytype] = stg.[apuk_localofficeid_entitytype],
		tgt.[apuk_localofficeidname] = stg.[apuk_localofficeidname],
		tgt.[apuk_localofficeidyominame] = stg.[apuk_localofficeidyominame],
		tgt.[apuk_name] = stg.[apuk_name],
		tgt.[apuk_regionid] = stg.[apuk_regionid],
		tgt.[apuk_regionid_entitytype] = stg.[apuk_regionid_entitytype],
		tgt.[apuk_regionidname] = stg.[apuk_regionidname],
		tgt.[apuk_reportingregion] = stg.[apuk_reportingregion],
		tgt.[apuk_reportingregion_entitytype] = stg.[apuk_reportingregion_entitytype],
		tgt.[apuk_reportingregionname] = stg.[apuk_reportingregionname],
		tgt.[apuk_reportingsubworldregion] = stg.[apuk_reportingsubworldregion],
		tgt.[apuk_reportingsubworldregion_entitytype] = stg.[apuk_reportingsubworldregion_entitytype],
		tgt.[apuk_reportingsubworldregionname] = stg.[apuk_reportingsubworldregionname],
		tgt.[apuk_subregion] = stg.[apuk_subregion],
		tgt.[apuk_subregion_entitytype] = stg.[apuk_subregion_entitytype],
		tgt.[apuk_subregionname] = stg.[apuk_subregionname],
		tgt.[apuk_worldregionid] = stg.[apuk_worldregionid],
		tgt.[apuk_worldregionid_entitytype] = stg.[apuk_worldregionid_entitytype],
		tgt.[apuk_worldregionidname] = stg.[apuk_worldregionidname],
		tgt.[createdby] = stg.[createdby],
		tgt.[createdby_entitytype] = stg.[createdby_entitytype],
		tgt.[createdbyname] = stg.[createdbyname],
		tgt.[createdbyyominame] = stg.[createdbyyominame],
		tgt.[createdon] = stg.[createdon],
		tgt.[createdonbehalfby] = stg.[createdonbehalfby],
		tgt.[createdonbehalfby_entitytype] = stg.[createdonbehalfby_entitytype],
		tgt.[createdonbehalfbyname] = stg.[createdonbehalfbyname],
		tgt.[createdonbehalfbyyominame] = stg.[createdonbehalfbyyominame],
		tgt.[importsequencenumber] = stg.[importsequencenumber],
		tgt.[modifiedby] = stg.[modifiedby],
		tgt.[modifiedby_entitytype] = stg.[modifiedby_entitytype],
		tgt.[modifiedbyname] = stg.[modifiedbyname],
		tgt.[modifiedbyyominame] = stg.[modifiedbyyominame],
		tgt.[modifiedon] = stg.[modifiedon],
		tgt.[modifiedonbehalfby] = stg.[modifiedonbehalfby],
		tgt.[modifiedonbehalfby_entitytype] = stg.[modifiedonbehalfby_entitytype],
		tgt.[modifiedonbehalfbyname] = stg.[modifiedonbehalfbyname],
		tgt.[modifiedonbehalfbyyominame] = stg.[modifiedonbehalfbyyominame],
		tgt.[organizationid] = stg.[organizationid],
		tgt.[organizationid_entitytype] = stg.[organizationid_entitytype],
		tgt.[organizationidname] = stg.[organizationidname],
		tgt.[overriddencreatedon] = stg.[overriddencreatedon],
		tgt.[SinkCreatedOn] = stg.[SinkCreatedOn],
		tgt.[SinkModifiedOn] = stg.[SinkModifiedOn],
		tgt.[statecode] = stg.[statecode],
		tgt.[statuscode] = stg.[statuscode],
		tgt.[timezoneruleversionnumber] = stg.[timezoneruleversionnumber],
		tgt.[utcconversiontimezonecode] = stg.[utcconversiontimezonecode],
		tgt.[versionnumber] = stg.[versionnumber]
	 FROM [synapse_ce].[apuk_localgroup] tgt
		INNER JOIN [staging_ce].[apuk_localgroup] stg
			ON tgt.[id] = stg.[id]
END
